1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.cupom.Cupom;
5	import com.loja.checkout.dto.ItemRequest;
6	import com.loja.checkout.dto.PedidoRequest;
7	import com.loja.checkout.dto.Regiao;
8	import com.loja.checkout.dto.ResumoResponse;
9	import com.loja.checkout.entrega.ModalidadeEntrega;
10	import com.loja.checkout.exception.CheckoutException;
11	import com.loja.checkout.pagamento.FormaPagamento;
12	import com.loja.checkout.pagamento.ResultadoPagamento;
13	import org.springframework.stereotype.Service;
14	
15	import java.math.BigDecimal;
16	import java.math.RoundingMode;
17	import java.util.List;
18	import java.util.Map;
19	import java.util.function.Function;
20	import java.util.stream.Collectors;
21	
22	@Service
23	public class ResumoService {
24	
25	    private final Map<String, ModalidadeEntrega> modalidades;
26	    private final Map<String, Cupom> cupons;
27	    private final Map<String, NivelClube> niveis;
28	    private final Map<String, FormaPagamento> formasPagamento;
29	
30	    public ResumoService(List<ModalidadeEntrega> modalidades,
31	                         List<Cupom> cupons,
32	                         List<NivelClube> niveis,
33	                         List<FormaPagamento> formasPagamento) {
34	        this.modalidades = modalidades.stream().collect(Collectors.toMap(ModalidadeEntrega::getCodigo, Function.identity()));
35	        this.cupons = cupons.stream().collect(Collectors.toMap(Cupom::getCodigo, Function.identity()));
36	        this.niveis = niveis.stream().collect(Collectors.toMap(NivelClube::getCodigo, Function.identity()));
37	        this.formasPagamento = formasPagamento.stream().collect(Collectors.toMap(FormaPagamento::getCodigo, Function.identity()));
38	    }
39	
40	    public ResumoResponse calcular(PedidoRequest pedido) {
41	        validarItens(pedido.itens());
42	
43	        NivelClube nivel = niveis.get(pedido.nivelClube());
44	        if (nivel == null) throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
45	
46	        Regiao regiao = Regiao.porCodigo(pedido.regiao());
47	        if (regiao == null) throw new CheckoutException("REGIAO_INVALIDA");
48	
49	        ModalidadeEntrega modalidade = modalidades.get(pedido.modalidadeEntrega());
50	        if (modalidade == null) throw new CheckoutException("MODALIDADE_INVALIDA");
51	
52	        BigDecimal pesoTotal = calcularPeso(pedido.itens());
53	        if (!modalidade.isDisponivel(pesoTotal)) throw new CheckoutException("MODALIDADE_INDISPONIVEL");
54	
55	        Cupom cupom = null;
56	        if (pedido.cupom() != null && !pedido.cupom().isEmpty()) {
57	            cupom = cupons.get(pedido.cupom());
58	            if (cupom == null) throw new CheckoutException("CUPOM_INVALIDO");
59	        }
60	
61	        BigDecimal subtotal = calcularSubtotal(pedido.itens());
62	
63	        if (cupom != null && !cupom.isAplicavel(subtotal, pedido.itens())) {
64	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
65	        }
66	
67	        FormaPagamento forma = formasPagamento.get(pedido.formaPagamento());
68	        if (forma == null) throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
69	
70	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
71	        if (!forma.isParcelamentoValido(parcelas)) throw new CheckoutException("PARCELAMENTO_INVALIDO");
72	
73	        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
74	        if (nivel.isFreteGratis()) {
75	            frete = BigDecimal.ZERO.setScale(2);
76	        }
77	
78	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
79	        if (cupom != null) {
80	            descontoCupom = cupom.calcularDesconto(subtotal, pedido.itens(), frete);
81	        }
82	
83	        BigDecimal seguro = subtotal.multiply(regiao.getTaxaSeguro()).setScale(2, RoundingMode.HALF_EVEN);
84	
85	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
86	
87	        if (!forma.isDisponivel(totalPedido)) throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
88	
89	        ResultadoPagamento resultado = forma.calcular(totalPedido, parcelas);
90	
91	        BigDecimal credito = nivel.calcularCredito(subtotal);
92	        boolean brinde = nivel.temBrinde(subtotal);
93	
94	        return new ResumoResponse(
95	                subtotal,
96	                descontoCupom,
97	                frete,
98	                modalidade.getPrazoDias(),
99	                seguro,
100	                resultado.ajuste(),
101	                resultado.totalFinal(),
102	                resultado.parcelas(),
103	                resultado.valorParcela(),
104	                credito,
105	                brinde
106	        );
107	    }
108	
109	    private void validarItens(List<ItemRequest> itens) {
110	        if (itens == null || itens.isEmpty()) throw new CheckoutException("PEDIDO_INVALIDO");
111	        for (ItemRequest item : itens) {
112	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0)
113	                throw new CheckoutException("PEDIDO_INVALIDO");
114	            if (item.quantidade() == null || item.quantidade() <= 0)
115	                throw new CheckoutException("PEDIDO_INVALIDO");
116	            if (item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0)
117	                throw new CheckoutException("PEDIDO_INVALIDO");
118	        }
119	    }
120	
121	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
122	        BigDecimal subtotal = BigDecimal.ZERO;
123	        for (ItemRequest item : itens) {
124	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
125	        }
126	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
127	    }
128	
129	    private BigDecimal calcularPeso(List<ItemRequest> itens) {
130	        BigDecimal peso = BigDecimal.ZERO;
131	        for (ItemRequest item : itens) {
132	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
133	        }
134	        return peso;
135	    }
136	}
