6	public enum Regiao {
7	
8	    SUDESTE(new BigDecimal("0.01")),
9	    SUL(new BigDecimal("0.01")),
10	    CENTRO_OESTE(new BigDecimal("0.015")),
11	    NORTE(new BigDecimal("0.025")),
12	    NORDESTE(new BigDecimal("0.02"));
13	
14	    private static final Map<String, Regiao> POR_CODIGO = Map.of(
15	            "SUDESTE", SUDESTE,
16	            "SUL", SUL,
17	            "CENTRO_OESTE", CENTRO_OESTE,
18	            "NORTE", NORTE,
19	            "NORDESTE", NORDESTE
20	    );
21	
22	    private final BigDecimal taxaSeguro;
23	
24	    Regiao(BigDecimal taxaSeguro) {
25	        this.taxaSeguro = taxaSeguro;
26	    }
27	
28	    public BigDecimal getTaxaSeguro() {
29	        return taxaSeguro;
30	    }
31	
32	    public static Regiao porCodigo(String codigo) {
33	        return codigo == null ? null : POR_CODIGO.get(codigo);
34	    }
35	}
