1	package com.loja.checkout.pagamento;
2	
3	import org.springframework.stereotype.Component;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	
9	@Component
10	public class Cartao implements FormaPagamento {
11	
12	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
13	    private static final int MAX_SEM_JUROS = 3;
14	    private static final int MAX_PARCELAS = 12;
15	
16	    @Override
17	    public String getCodigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean isParcelamentoValido(int parcelas) {
23	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
24	    }
25	
26	    @Override
27	    public boolean isDisponivel(BigDecimal totalPedido) {
28	        return true;
29	    }
30	
31	    @Override
32	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
33	        if (parcelas <= MAX_SEM_JUROS) {
34	            BigDecimal valorParcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
35	            return new ResultadoPagamento(totalPedido, valorParcela, BigDecimal.ZERO.setScale(2), parcelas);
36	        }
37	
38	        BigDecimal um = BigDecimal.ONE;
39	        BigDecimal basePotencia = um.add(TAXA_MENSAL).pow(parcelas, MathContext.DECIMAL128);
40	        BigDecimal denominador = um.subtract(um.divide(basePotencia, 34, RoundingMode.HALF_EVEN));
41	        BigDecimal valorParcela = totalPedido.multiply(TAXA_MENSAL)
42	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
43	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
44	        BigDecimal ajuste = totalFinal.subtract(totalPedido);
45	        return new ResultadoPagamento(totalFinal, valorParcela, ajuste, parcelas);
46	    }
47	}
